import json

from pysepal import model
from traitlets import Any, Dict, List, Unicode

from deforestation_alerts.message import cm
from deforestation_alerts.scripts.custom_sources import normalize_sources


class AuxModel(model.Model):

    ############################################################################
    # optional auxiliary files that advanced users can input
    ############################################################################
    ccdc_layer = Any(None).tag(sync=True)
    "ccdc alerts generated by the users"

    custom_alerts = List(Dict(), default_value=[]).tag(sync=True)
    "user-defined custom alert sources, [{'name', 'asset'}] (RADD-shaped GEE assets); list order is the code slot. Always reassign, never mutate in place, so observers fire"

    mask_layer = Any(None).tag(sync=True)
    "layer to mask out alerts, for example, forest no forest"

    aux_layer = Any(None).tag(sync=True)
    "auxiliary layer that the user can visualize during alert analysis, for example, forest plantation or forest management areas"

    aux_layer_vis = Any(None).tag(sync=True)
    "auxiliary layer visualization parameters"

    attribute_raster = Any(None).tag(sync=True)
    "optional raster (GEE asset or local path) + per-band stats to attribute alerts"

    custom_report_template = Any(None).tag(sync=True)
    "User custom template for reports"

    ############################################################################
    # planet credentials
    ############################################################################

    def export_dictionary(self):
        dictionary = {
            "ccdc_layer": self.ccdc_layer,
            "custom_alerts": [dict(s) for s in self.custom_alerts],
            "mask_layer": self.mask_layer,
            "aux_layer": self.aux_layer,
            "aux_layer_vis": self.aux_layer_vis,
            "attribute_raster": self.attribute_raster,
            "custom_report_template": self.custom_report_template,
        }
        return dictionary

    def import_from_dictionary(self, file_path):
        """
        Import class attributes from a JSON file.
        Args:
            file_path (str): Path to the JSON file.
        """
        try:
            # with open(file_path, 'r') as f:
            #     data = json.load(f)
            data = file_path
            # Update attributes
            self.ccdc_layer = data.get("ccdc_layer", self.ccdc_layer)
            if "custom_alerts" in data:
                self.custom_alerts = normalize_sources(data["custom_alerts"])
            elif data.get("custom_alert_layer") and data.get("custom_alert_name"):
                # Recipes saved before multiple sources: one legacy source.
                self.custom_alerts = normalize_sources(
                    [{"name": data["custom_alert_name"], "asset": data["custom_alert_layer"]}]
                )
            elif "custom_alert_layer" in data or "custom_alert_name" in data:
                self.custom_alerts = []
            self.mask_layer = data.get("mask_layer", self.mask_layer)
            self.aux_layer = data.get("aux_layer", self.aux_layer)
            self.aux_layer_vis = data.get("aux_layer_vis", self.aux_layer_vis)
            self.attribute_raster = data.get(
                "attribute_raster", self.attribute_raster
            )
            self.custom_report_template = data.get(
                "custom_report_template", self.custom_report_template
            )

        except (FileNotFoundError, json.JSONDecodeError) as e:
            print(f"Error loading JSON file: {e}")
